26	    private static Range findRange(int[] values) {
27	        int minValue = values[0];
28	        int maxValue = values[0];
29	
30	        for (int i = 1; i < values.length; i++) {
31	            int value = values[i];
32	            if (value < minValue) {
33	                minValue = value;
34	            }
35	            if (value > maxValue) {
36	                maxValue = value;
37	            }
38	        }
39	
40	        return new Range(minValue, maxValue);
41	    }
