43	    private static int[] buildCounts(int[] values, Range range) {
44	        int[] counts = new int[range.size()];
45	        int offset = range.minValue();
46	
47	        for (int value : values) {
48	            counts[value - offset]++;
49	        }
50	
51	        return counts;
52	    }
