60	    private static int[] buildSortedArray(int[] values, int[] counts, int minValue) {
61	        int[] sortedValues = new int[values.length];
62	
63	        for (int i = values.length - 1; i >= 0; i--) {
64	            int value = values[i];
65	            int countIndex = value - minValue;
66	            sortedValues[counts[countIndex] - 1] = value;
67	            counts[countIndex]--;
68	        }
69	
70	        return sortedValues;
71	    }
